1	/**
2	 * Claude Code in-sandbox runner.
3	 *
4	 * This file is shipped INTO the sandbox by the orchestrator and executed there as
5	 * `node __agent_eval__/run.mjs '<AgentRunInput JSON>'`. It is intentionally
6	 * ZERO-DEPENDENCY (only `node:*` builtins) because the sandbox only has the
7	 * fixture's own deps + the installed `claude` CLI — it cannot import anything from
8	 * the @vercel/agent-eval package.
9	 *
10	 * Dual mode:
11	 *   - runnable: invoked directly → reads argv, runs the agent, writes the result
12	 *     file + prints a status line, exits 0.
13	 *   - importable: `import { runAgent } from './run.mjs'` → returns a RunnerResult
14	 *     (no file write, no exit). This is what a future in-sandbox judge reuses.
15	 *
16	 * `buildClaudeCodeCliArgs` and `extractObservedModelFromClaudeTranscript` are
17	 * exported so the host unit tests can verify them directly (the test imports them
18	 * from this very file, so there is no risk of the tested logic drifting from the
19	 * logic the sandbox actually runs).
20	 */
21	
22	import { spawnSync } from 'node:child_process';
23	import { mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
24	import { homedir } from 'node:os';
25	import { dirname, join } from 'node:path';
26	import { fileURLToPath } from 'node:url';
27	
28	/**
29	 * Build the Claude Code CLI argument list.
30	 *
31	 * Order is regression-sensitive (preserved verbatim from the old adapter):
32	 * `--allowedTools` is variadic — it keeps consuming positional tokens until the
33	 * next flag. So (1) the tools must be a single comma-separated value, and (2)
34	 * `--allowedTools` must be followed by another flag, never directly by the prompt.
35	 * `--dangerously-skip-permissions` is always emitted and terminates the variadic
36	 * capture before the trailing positional prompt (the #141 regression).
37	 *
38	 * @param {{prompt:string, model?:string, webResearch?:boolean, disableBundledSkills?:boolean, agentOptions?:Record<string,unknown>}} input
39	 * @returns {string[]}
40	 */
41	export function buildClaudeCodeCliArgs(input) {
42	  const cliArgs = ['--print'];
43	  if (input.disableBundledSkills) {
44	    // CLI-scoped settings override only this run and preserve explicitly
45	    // installed project/user skills; --bare would hide treatment skills too.
46	    cliArgs.push('--settings', JSON.stringify({ disableBundledSkills: true }));
47	  }
48	  if (input.webResearch) {
49	    cliArgs.push('--allowedTools', 'WebSearch,WebFetch');
50	  }
51	  if (input.model) {
52	    cliArgs.push('--model', input.model);
53	  }
54	  cliArgs.push('--dangerously-skip-permissions');
55	  const effort = input.agentOptions?.effort;
56	  if (effort) {
57	    cliArgs.push('--effort', String(effort));
58	  }
59	  cliArgs.push(input.prompt);
60	  return cliArgs;
61	}
62	
63	/**
64	 * Scan a Claude Code transcript (JSONL) for the last `message.model` seen.
65	 * Preserved verbatim from the old adapter. Non-JSON lines are ignored.
66	 *
67	 * @param {string|undefined|null} transcript
68	 * @returns {string|undefined}
69	 */
70	export function extractObservedModelFromClaudeTranscript(transcript) {
71	  if (!transcript) return undefined;
72	
73	  let observedModel;
74	  for (const line of transcript.split('\n')) {
75	    if (!line.trim()) continue;
76	    try {
77	      const event = JSON.parse(line);
78	      if (typeof event.message?.model === 'string') {
79	        observedModel = event.message.model;
80	      }
81	    } catch {
82	      // Ignore non-JSON transcript lines.
83	    }
84	  }
85	  return observedModel;
86	}
87	
88	/**
89	 * Locate + read the Claude Code transcript file.
90	 *
91	 * Claude Code writes JSONL transcripts to
92	 * `~/.claude/projects/{cwd-with-slashes-as-dashes}/{session}.jsonl`. We pick the
93	 * newest `.jsonl` by mtime — the equivalent of the old adapter's
94	 * `ls -t ~/.claude/projects/<path>/*.jsonl | head -1`.
95	 *
96	 * Best-effort: any failure → null (never throws).
97	 *
98	 * @param {string} cwd post-relocation sandbox cwd (e.g. /workspace)
99	 * @returns {string|null}
100	 */
101	function captureClaudeTranscript(cwd) {
102	  try {
103	    const projectPath = cwd.replace(/\//g, '-');
104	    const dir = join(homedir(), '.claude', 'projects', projectPath);
105	    const newest = readdirSync(dir)
106	      .filter((f) => f.endsWith('.jsonl'))
107	      .map((f) => {
108	        const full = join(dir, f);
109	        return { full, mtime: statSync(full).mtimeMs };
110	      })
111	      .sort((a, b) => b.mtime - a.mtime)[0];
112	    if (!newest) return null;
113	    return readFileSync(newest.full, 'utf8') || null;
114	  } catch {
115	    return null;
116	  }
117	}
118	
119	/**
120	 * Run Claude Code over the workspace at `input.cwd` and return a RunnerResult.
121	 *
122	 * Auth (ANTHROPIC_BASE_URL/ANTHROPIC_AUTH_TOKEN/...) arrives via process.env — the
123	 * orchestrator sets it on the `node run.mjs` invocation, and we pass process.env
124	 * straight through to the CLI. The runner never handles secrets itself.
125	 *
126	 * @param {import('../plugin/contract.js').AgentRunInput} input
127	 * @returns {Promise<import('../plugin/contract.js').RunnerResult>}
128	 */
129	export async function runAgent(input) {
130	  const args = buildClaudeCodeCliArgs(input);
131	
132	  // spawnSync (not a shell string): the prompt is a plain argv element, so there is
133	  // no shell quoting/escaping to get wrong. Blocking is fine — the runner has
134	  // nothing else to do while the agent works. The sandbox-level timeout bounds it.
135	  const res = spawnSync('claude', args, {
136	    cwd: input.cwd,
137	    env: process.env,
138	    encoding: 'utf8',
139	    maxBuffer: 64 * 1024 * 1024,
140	  });
141	
142	  const stdout = res.stdout || '';
143	  const stderr = res.stderr || '';
144	  // Preserve the old concatenation order: stdout THEN stderr.
145	  const output = stdout + stderr;
146	  // spawnSync sets status=null + error when the binary can't be spawned at all.
147	  const agentExitCode = res.status == null ? -1 : res.status;
148	
149	  // Capture transcript + observed model regardless of success (the old adapter did
150	  // this even on the non-zero-exit path).
151	  const transcript = captureClaudeTranscript(input.cwd);
152	  const observedModel = extractObservedModelFromClaudeTranscript(transcript) ?? null;
153	
154	  if (res.error || agentExitCode !== 0) {
155	    // Mirror the old error string: last 5 lines of output, else a coded fallback.
156	    const errorLines = output.trim().split('\n').slice(-5).join('\n');
157	    const fallback = res.error
158	      ? `Failed to run claude: ${res.error.message}`
159	      : `Claude Code exited with code ${agentExitCode}`;
160	    return {
161	      ok: false,
162	      output,
163	      transcript,
164	      observedModel,
165	      error: errorLines || fallback,
166	      agentExitCode,
167	    };
168	  }
169	
170	  return { ok: true, output, transcript, observedModel, error: null, agentExitCode };
171	}
172	
173	/* ─────────────────────────── runnable (CLI) entry ─────────────────────────── */
174	
175	// True when this file is executed directly (`node run.mjs ...`), false when imported.
176	const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
177	
178	if (isMain) {
179	  // argv[2] is the AgentRunInput JSON (never contains secrets).
180	  const input = JSON.parse(process.argv[2]);
181	
182	  // Always produce a RunnerResult, even if the runner itself throws, so the host
183	  // always has a result file to read (node exit code stays 0 except on a truly
184	  // unrecoverable crash before we can write).
185	  let result;
186	  try {
187	    result = await runAgent(input);
188	  } catch (e) {
189	    result = {
190	      ok: false,
191	      output: '',
192	      transcript: null,
193	      observedModel: null,
194	      error: e && e.message ? e.message : String(e),
195	      agentExitCode: -1,
196	    };
197	  }
198	
199	  // Source of truth: the result file the host reads back via sandbox.readFile.
200	  try {
201	    mkdirSync(dirname(input.resultPath), { recursive: true });
202	    writeFileSync(input.resultPath, JSON.stringify(result));
203	  } catch {
204	    // If the file can't be written, the host falls back to the marker line below.
205	  }
206	
207	  // Fallback channel: a compact status line (no transcript — it can be huge).
208	  process.stdout.write(
209	    '__AGENT_RESULT__ ' +
210	      JSON.stringify({
211	        ok: result.ok,
212	        observedModel: result.observedModel,
213	        error: result.error,
214	        agentExitCode: result.agentExitCode,
215	      }) +
216	      '\n'
217	  );
218	
219	  // Exit 0: "the runner ran". Agent success/failure is conveyed via result.ok, not
220	  // the node exit code (the host distinguishes the two).
221	  process.exit(0);
222	}
